                system = "x86_64-linux";
                modules = [
                    (import-tree ./projector)
                    (import-tree ./share)
                    disko.nixosModules.disko
                    home-manager.nixosModules.home-manager
                    {
                        home-manager = {
                            useGlobalPkgs = true;
                            useUserPackages = true;
                            users.projector = {
                                imports = [
                                    plasma-manager.homeModules.plasma-manager
                                    nixvim.homeModules.nixvim
                                    (import-tree ./projector/modules/_home)
                                    (import-tree ./share/_home)
                                ];
                                home.stateVersion = "26.05";
                            };
                            users.admin = {
                                imports = [
                                    nixvim.homeModules.nixvim
                                    (import-tree ./share/_home)
                                ];
                                home.stateVersion = "26.05";
                            };
                            backupFileExtension = "hm-backup";
                        };
                    }
                ];
            };
            nixosConfigurations.X60s = nixpkgs-23_11.lib.nixosSystem {
                system = "i686-linux";
                specialArgs = {
                    inherit inputs;
                };
                modules = [
                    (import-tree ./X60s)
                        home-manager-23_11.nixosModules.home-manager
                        {
                            home-manager = {
                                useGlobalPkgs = true;
                                useUserPackages = true;
                                extraSpecialArgs = {
                                    inherit inputs;
                                };
                                users.zhaolun = {
                                    imports = [
                                        nixvim-23_11.homeManagerModules.nixvim
                                        (import-tree ./X60s/modules/_home)
                                    ];
                                };
                            };
                        }
                ];
            };
        };
}

